steps.script:
for m in GameState.state.units["U_KOMMANDOS_H"].models:
	m["alive"] = true
	m["current_wounds"] = 1
return GameState.state.units["U_KOMMANDOS_H"].models.size()

var w = GameState.state.units["U_WITCHSEEKERS_C"]
for i in range(w.models.size()):
	w.models[i].position = {"x": 760.0, "y": 2050.0 + i * 45.0}
tree.current_scene._sync_all_token_positions()
return true

var st = GameState.state
var bad = []
var t = st.units["U_BATTLEWAGON_G"].models[0].duplicate()
t["alive"] = true
var placed = []
for m in st.units["U_KOMMANDOS_H"].models:
	if not m.get("alive", true):
		continue
	if m.get("position", null) == null:
		bad.append("unplaced survivor")
		continue
	var mm = m.duplicate()
	mm["position"] = Vector2(float(m.position.x), float(m.position.y))
	placed.append(mm)
var enemies = []
for m in st.units["U_WITCHSEEKERS_C"].models:
	var e = m.duplicate()
	e["position"] = Vector2(float(m.position.x), float(m.position.y))
	enemies.append(e)
for i in range(placed.size()):
	var m = placed[i]
	if Measurement.model_outside_board(m.position, m):
		bad.append("off board")
	if Measurement.models_overlap(m, t):
		bad.append("on the wreck")
	if Measurement.model_edge_to_point_distance_px(t, m.position) + Measurement.base_extent_px(m) > Measurement.inches_to_px(6.0) + 0.5:
		bad.append("not wholly within 6")
	for j in range(i + 1, placed.size()):
		if Measurement.models_overlap(m, placed[j]):
			bad.append("overlap")
	for e in enemies:
		if Measurement.is_in_engagement_range_shape_aware(m, e):
			bad.append("engaged")
	var linked = placed.size() == 1
	for j in range(placed.size()):
		if j != i and Measurement.model_to_model_distance_inches(m, placed[j]) <= 2.01:
			linked = true
	if not linked:
		bad.append("coherency")
print("[P1-4] " + str(placed.size()) + " Kommandos set up; violations=" + str(bad))
return bad.size()

var t = GameState.state.units["U_BATTLEWAGON_G"].models[0].duplicate()
t["alive"] = true
var best = 999.0
for m in GameState.state.units["U_KOMMANDOS_H"].models:
	if m.get("alive", true) and m.get("position", null) != null:
		var mm = m.duplicate()
		mm["position"] = Vector2(float(m.position.x), float(m.position.y))
		best = min(best, Measurement.model_to_model_distance_inches(mm, t))
return best
